import {pageHeader,backButton,iconButton,backIcon,statCard,disclosure} from '../primitives.js?v=31';
export const faqPage = () => `<section id="faq" class="tab" hidden>${pageHeader({title:"Вопросы и ответы",startContent:backButton('profile')})}${disclosure("Осколки — путь к нужному предмету.","<article class=\"compensation panel\"><div><p class=\"eyebrow\">ПОВТОРЫ ТОЖЕ ПОЛЕЗНЫ</p><p>Монеты открывают сундуки. Осколки позволяют выбрать конкретную фигурку или доску в коллекции. Их нельзя обменять обратно на монеты.</p><button class=\"quiet\" data-go=\"collection\">Открыть коллекцию</button></div><div class=\"table-scroll\"><table><caption>Компенсация за дубликат / цена создания, в осколках</caption><thead><tr><th>Редкость</th><th>Фигурка</th><th>Доска</th></tr></thead><tbody><tr><td>Обычная</td><td>8 / 40</td><td>16 / 80</td></tr><tr><td class=\"rare\">Редкая</td><td>20 / 100</td><td>40 / 200</td></tr><tr><td class=\"epic\">Эпическая</td><td>60 / 300</td><td>120 / 600</td></tr><tr><td class=\"legendary\">Легендарная</td><td>150 / 750</td><td>300 / 1500</td></tr></tbody></table></div></article>")}${disclosure("Очки и монеты","<article class=\"panel\"><p>Очки на доске — разница стоимости оставшихся фигур: пешка 1, конь и слон 3, ладья 5, ферзь 9. Это не рейтинг и не монеты.</p><p>За завершение партии — 10 монет. За каждые 2 ваших хода — ещё 1 монета, максимум 20 за 40 ходов. Победа добавляет 10 монет, ничья — 5, поражение — 0. Например, победа за 20 ваших ходов принесёт 30 монет.</p><p>Считаются только ваши ходы в итоговой партии, без ходов ИИ и отменённых ходов. Просмотр истории ничего не добавляет. Рейтинг, время игры и взятые фигуры на награду не влияют.</p><p>При мате или игровой ничьей награда начисляется даже за короткую партию. При сдаче раньше 10 ваших ходов — 0 монет; начиная с 10-го — награда за завершение и ходы без бонуса за результат. Незавершённая партия и отмена из-за ошибки ИИ монет не приносят. Каждая партия оплачивается один раз.</p><p>Сдача до вашего первого хода не приносит монет и не попадает в историю или статистику. Первый ход ИИ не считается вашим ходом.</p></article>")}${disclosure("Что выпадает из сундука?","<article class=\"panel\"><p>Одна фигурка — 85%, одна доска — 10%, только 15 осколков — 5%.</p><p>Редкость выпавшего предмета: обычная — 60%, редкая — 30%, эпическая — 9%, легендарная — 1%.</p><p>Десятое открытие без эпического или легендарного предмета гарантирует одну из этих редкостей: 90% / 10%. На гарантии фигурка выпадает с вероятностью 90%, доска — 10%. Повторы возможны и компенсируются осколками.</p></article>")}${disclosure("Как работает адаптация?","<p>Победа повышает рейтинг, поражение и сдача снижают его. Ничья учитывает разницу уровней. Первые 10 партий быстрее уточняют оценку; затем изменения становятся плавнее.</p><p>Соперник обычно получает целевой уровень на 100 ниже вашего рейтинга, в диапазоне 100–1400. Сила немного варьируется между партиями и фиксируется при старте. Cognitive v2 выбирает ход на основе ограниченного восприятия, расчёта и характера соперника. На верхней границе используется Stockfish 19. Числа обозначают внутреннюю шкалу, а не подтверждённый человеческий Elo.</p><p>Это локальная шкала приложения, не рейтинг FIDE или Chess.com. Награда не зависит от рейтинга. Прогресс хранится на этом устройстве.</p><p><a href=\"./engine-info.html\" target=\"_blank\" rel=\"noopener\">ИИ: модель, версия и лицензии</a></p>")}${disclosure("Играйте и пополняйте коллекцию","<article class=\"reward-card\" id=\"play-rewards\"><span class=\"reward-icon\">◈</span><div><p id=\"profile-rewards\"></p><small>До 40 монет за победу. При сдаче — после 10 ваших ходов.</small></div></article>")}</section>`;
